Object.assign(SNIP,{});PRESET_NOTES["l45"]={"Ví dụ: Leo cầu thang bước 1 hoặc 2": "dp = 1, 1, 2, 3, 5, 8, 13: chính là dãy Fibonacci. Có 13 cách lên bậc 6.", "Ví dụ: Có bậc bị hỏng": "Bậc hỏng có dp = 0 nên không đóng góp gì cho các bậc sau. dp = 1, 1, 2, 0, 2, 0, 2, 2: chỉ còn 2 cách tới bậc 7 (phải bước 2 bậc qua mỗi bậc hỏng).", "Ví dụ: Chi phí nhỏ nhất": "Đếm thì cộng, tối ưu thì lấy min. dp = 0, 10, 15, 30, 20, 45, 30: đường rẻ nhất 0 → 2 → 4 → 6 tốn 15 + 5 + 10 = 30.", "Ví dụ: Thêm một chiều cho trạng thái": "Không được bước 2 bậc hai lần liền nhau: còn 9 cách thay vì 13 (bỏ 2+2+2, 2+2+1+1, 1+2+2+1, 1+1+2+2). Cột 1 của hàng i chỉ đọc cột 0 của hàng i − 2.", "Lỗi: quên trường hợp cơ sở": "In 8 thay vì 13: dp[2] chỉ còn 1 vì thiếu cách “bước 2 bậc từ mặt đất”. Cả dãy lệch theo. Mỗi lần viết dp, kiểm tra tay vài ô đầu."};EX_HINTS["l45"]=[["dp[i]: số cách tới đúng bậc i. Bước cuối dài s (1 ≤ s ≤ k) đến từ bậc i − s.", "Bậc hỏng: dp = 0, các bậc sau tự nhiên không đi qua nó.", "O(n · k) là đủ. (Muốn nhanh hơn: giữ tổng trượt của k ô gần nhất.)"], ["dp[i]: sức nhỏ nhất để đứng ở hòn i. dp[0] = 0.", "Cú nhảy cuối từ i − 1 hoặc i − 2: dp[i] = min(dp[i−1] + |h[i] − h[i−1]|, dp[i−2] + |h[i] − h[i−2]|).", "Tham lam “nhảy tới hòn gần độ cao nhất” không đúng; thử với 30 10 60 10 60 50."], ["Chỉ biết số chuỗi độ dài i là không đủ: cần biết khối chữ giống nhau ở cuối dài 1 hay 2.", "mot[i]: chuỗi kết thúc bằng khối dài 1; hai[i]: khối dài 2. Thêm chữ khác: (mot + hai) · 2 chuỗi vào mot. Thêm chữ giống: chỉ từ mot, vào hai.", "Cơ sở n = 1: mot = 3, hai = 0. Chỉ cần giữ hai số của độ dài trước."]];
/* ===================== BÀI 45 · Trạng thái và công thức truy hồi qua bài leo cầu thang ===================== */
/* Bài 45 · Trạng thái và công thức truy hồi qua bài leo cầu thang
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR45=[{label:"Ví dụ: Leo cầu thang bước 1 hoặc 2",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    int dp[7];\n    dp[0] = 1;                         // đứng yên ở mặt đất: một cách\n    dp[1] = 1;\n    for (int i = 2; i <= n; i++)\n        dp[i] = dp[i - 1] + dp[i - 2]; // bước cuối 1 bậc hoặc 2 bậc\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]}],py:{code:"n = 6\ndp = [0] * (n + 1)\ndp[0] = 1                              # đứng yên ở mặt đất: một cách\ndp[1] = 1\nfor i in range(2, n + 1):\n    dp[i] = dp[i - 1] + dp[i - 2]      # bước cuối 1 bậc hoặc 2 bậc\nprint(dp[n])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        int[] dp = new int[n + 1];\n        dp[0] = 1;                             // đứng yên ở mặt đất: một cách\n        dp[1] = 1;\n        for (int i = 2; i <= n; i++)\n            dp[i] = dp[i - 1] + dp[i - 2];     // bước cuối 1 bậc hoặc 2 bậc\n        Console.WriteLine(dp[n]);\n    }\n}"}},{label:"Ví dụ: Có bậc bị hỏng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 7;\n    bool hong[8] = {false, false, false, true, false, true, false, false};   // bậc 3 và 5 hỏng\n    int dp[8];\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        if (hong[i]) { dp[i] = 0; continue; }   // không được đặt chân lên\n        dp[i] = dp[i - 1];\n        if (i >= 2) dp[i] += dp[i - 2];\n    }\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]}],py:{code:"n = 7\nhong = {3, 5}                          # bậc 3 và 5 hỏng\ndp = [0] * (n + 1)\ndp[0] = 1\nfor i in range(1, n + 1):\n    if i in hong:                      # không được đặt chân lên\n        continue\n    dp[i] = dp[i - 1] + (dp[i - 2] if i >= 2 else 0)\nprint(dp[n])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 7;\n        bool[] hong = new bool[n + 1];\n        hong[3] = hong[5] = true;              // bậc 3 và 5 hỏng\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++)\n        {\n            if (hong[i]) continue;             // không được đặt chân lên\n            dp[i] = dp[i - 1];\n            if (i >= 2) dp[i] += dp[i - 2];\n        }\n        Console.WriteLine(dp[n]);\n    }\n}"}},{label:"Ví dụ: Chi phí nhỏ nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int cost[7] = {0, 10, 15, 20, 5, 25, 10};   // đặt chân lên bậc i tốn cost[i]\n    int n = 6;\n    int dp[7];                         // dp[i]: chi phí nhỏ nhất để đứng ở bậc i\n    dp[0] = 0;\n    dp[1] = cost[1];\n    for (int i = 2; i <= n; i++)\n        dp[i] = cost[i] + min(dp[i - 1], dp[i - 2]);\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]},{type:"cells",of:"cost",ptr:["i"]}],py:{code:"cost = [0, 10, 15, 20, 5, 25, 10]     # đặt chân lên bậc i tốn cost[i]\nn = 6\ndp = [0] * (n + 1)                     # dp[i]: chi phí nhỏ nhất để đứng ở bậc i\ndp[1] = cost[1]\nfor i in range(2, n + 1):\n    dp[i] = cost[i] + min(dp[i - 1], dp[i - 2])\nprint(dp[n])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] cost = { 0, 10, 15, 20, 5, 25, 10 };   // đặt chân lên bậc i tốn cost[i]\n        int n = 6;\n        int[] dp = new int[n + 1];             // dp[i]: chi phí nhỏ nhất để đứng ở bậc i\n        dp[1] = cost[1];\n        for (int i = 2; i <= n; i++)\n            dp[i] = cost[i] + Math.Min(dp[i - 1], dp[i - 2]);\n        Console.WriteLine(dp[n]);\n    }\n}"}},{label:"Ví dụ: Thêm một chiều cho trạng thái",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    int dp[7][2] = {};                 // dp[i][0]: bước cuối 1 bậc; dp[i][1]: bước cuối 2 bậc\n    dp[0][0] = 1;                      // mặt đất: coi như vừa bước 1 (được phép bước 2 tiếp)\n    for (int i = 1; i <= n; i++) {\n        dp[i][0] = dp[i - 1][0] + dp[i - 1][1];\n        if (i >= 2) dp[i][1] = dp[i - 2][0];   // không bước 2 hai lần liên tiếp\n    }\n    cout << dp[n][0] + dp[n][1] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i"]}],py:{code:"n = 6\ndp = [[0, 0] for _ in range(n + 1)]    # dp[i][0]: bước cuối 1 bậc; dp[i][1]: bước cuối 2 bậc\ndp[0][0] = 1                           # mặt đất: coi như vừa bước 1 (được phép bước 2 tiếp)\nfor i in range(1, n + 1):\n    dp[i][0] = dp[i - 1][0] + dp[i - 1][1]\n    if i >= 2:\n        dp[i][1] = dp[i - 2][0]        # không bước 2 hai lần liên tiếp\nprint(dp[n][0] + dp[n][1])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        int[][] dp = new int[n + 1][];         // dp[i][0]: bước cuối 1 bậc; dp[i][1]: bước cuối 2 bậc\n        for (int i = 0; i <= n; i++) dp[i] = new int[2];\n        dp[0][0] = 1;                          // mặt đất: coi như vừa bước 1 (được phép bước 2 tiếp)\n        for (int i = 1; i <= n; i++)\n        {\n            dp[i][0] = dp[i - 1][0] + dp[i - 1][1];\n            if (i >= 2) dp[i][1] = dp[i - 2][0];   // không bước 2 hai lần liên tiếp\n        }\n        Console.WriteLine(dp[n][0] + dp[n][1]);\n    }\n}"}},{label:"Lỗi: quên trường hợp cơ sở",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    int dp[7] = {0};                   // SAI: quên đặt dp[0] = 1\n    dp[1] = 1;\n    for (int i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]}],py:{code:"n = 6\ndp = [0] * (n + 1)                     # SAI: quên đặt dp[0] = 1\ndp[1] = 1\nfor i in range(2, n + 1):\n    dp[i] = dp[i - 1] + dp[i - 2]\nprint(dp[n])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        int[] dp = new int[n + 1];             // SAI: quên đặt dp[0] = 1\n        dp[1] = 1;\n        for (int i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];\n        Console.WriteLine(dp[n]);\n    }\n}"}}];
const sim45=makeSim2(document.getElementById("sim-l45"),{id:"s45",presets:PR45});
makeEx2(document.getElementById("ex-l45"),sim45,[{t:"Cầu thang có bậc hỏng",d:"Cầu thang n bậc; mỗi lần bước lên 1, 2, …, hoặc k bậc; m bậc bị hỏng không được đặt chân. Đầu vào: dòng 1 là n và k (1 ≤ n ≤ 10^5, 1 ≤ k ≤ 100); dòng 2 bắt đầu bằng m (0 ≤ m < n), tiếp theo là m số hiệu bậc hỏng (khác nhau, trong 1 … n − 1). Đầu ra: số cách từ bậc 0 lên bậc n, lấy dư cho 10^9 + 7.",tests:[{in:"6 2\n0",out:"13"},{in:"7 2\n2 3 5",out:"2"},{in:"5 3\n1 2",out:"5"},{in:"4 1\n1 2",out:"0"},{in:"10 10\n0",out:"512"},{in:"50 4\n4 7 14 21 22",out:"538686965"},{in:"300 5\n43 3 10 17 24 31 38 45 52 59 66 73 80 87 94 101 108 115 122 129 136 143 150 157 164 171 178 185 192 199 206 213 220 227 234 241 248 255 262 269 276 283 290 297",out:"268450404"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    int n, k, m;\n    cin >> n >> k >> m;\n    vector<bool> hong(n + 1, false);\n    for (int j = 0; j < m; j++) {\n        int b;\n        cin >> b;\n        hong[b] = true;\n    }\n    const long long MOD = 1000000007;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    // dp[i] = tổng dp[i-1] … dp[i-k] (bỏ qua chỉ số âm); bậc hỏng giữ 0\n    cout << dp[n] << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const b=[];for(let i=7;i<n;i+=7)b.push(i);return n+" 3\n"+[b.length,...b].join(" ")},ns:[250,500,1000,2000],need:"n",limit:n=>80*n+300,why:"Đệ quy thử mọi bước mà không nhớ tốn thời gian cấp số mũ."},py:{start:"n, k = map(int, input().split())\nhong = set(list(map(int, input().split()))[1:])     # bỏ số đầu (m)\nMOD = 10**9 + 7\ndp = [0] * (n + 1)\ndp[0] = 1\n# dp[i] = tổng dp[i-1] … dp[i-k] (bỏ qua chỉ số âm); bậc hỏng giữ 0\nprint(dp[n])",hints:["dp[i]: số cách tới đúng bậc i. Bước cuối dài s (1 ≤ s ≤ k) đến từ bậc i − s.","Bậc hỏng: dp = 0, các bậc sau tự nhiên không đi qua nó.","O(n · k) là đủ. (Muốn nhanh hơn: giữ tổng trượt của k ô gần nhất.)"]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nk = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nk[0], k = nk[1];\n        int[] b = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);   // b[0] = m, rồi m bậc hỏng\n        bool[] hong = new bool[n + 1];\n        for (int j = 1; j < b.Length; j++) hong[b[j]] = true;\n        const long MOD = 1000000007;\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        // dp[i] = tổng dp[i-1] … dp[i-k] (bỏ qua chỉ số âm); bậc hỏng giữ 0\n        Console.WriteLine(dp[n]);\n    }\n}",hints:["dp[i]: số cách tới đúng bậc i. Bước cuối dài s (1 ≤ s ≤ k) đến từ bậc i − s.","Dòng 2: phần tử đầu là m, các bậc hỏng bắt đầu từ chỉ số 1.","O(n · k) là đủ. (Muốn nhanh hơn: giữ tổng trượt của k ô gần nhất.)"]}},{t:"Ếch nhảy đá",d:"Có n hòn đá, hòn i cao hᵢ. Con ếch ở hòn 1, mỗi lần nhảy tới hòn i + 1 hoặc i + 2, tốn |hᵢ − hⱼ| sức (j là hòn tới). Đầu vào: n (1 ≤ n ≤ 10^5) và n số hᵢ (1 ≤ hᵢ ≤ 10^4). Đầu ra: tổng sức nhỏ nhất để tới hòn n.",tests:[{in:"4\n10 30 40 20",out:"30"},{in:"2\n10 10",out:"0"},{in:"1\n5",out:"0"},{in:"6\n30 10 60 10 60 50",out:"40"},{in:"60\n1 38 75 12 49 86 23 60 97 34 71 8 45 82 19 56 93 30 67 4 41 78 15 52 89 26 63 100 37 74 11 48 85 22 59 96 33 70 7 44 81 18 55 92 29 66 3 40 77 14 51 88 25 62 99 36 73 10 47 84",out:"1175"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> h(n);\n    for (int i = 0; i < n; i++) cin >> h[i];\n    vector<long long> dp(n, 0);        // dp[i]: sức nhỏ nhất để tới hòn i (đánh số từ 0)\n    // xét cú nhảy cuối: từ i-1 hoặc từ i-2\n    cout << dp[n - 1] << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%10000+1).join(" "),ns:[500,1000,2000,4000],need:"n",limit:n=>60*n+300,why:"Thử mọi đường nhảy là cấp số mũ."},py:{start:"n = int(input())\nh = list(map(int, input().split()))\ndp = [0] * n                   # dp[i]: sức nhỏ nhất để tới hòn i (đánh số từ 0)\n# xét cú nhảy cuối: từ i-1 hoặc từ i-2\nprint(dp[n - 1])",hints:["dp[i]: sức nhỏ nhất để đứng ở hòn i. dp[0] = 0.","Cú nhảy cuối từ i − 1 hoặc i − 2: dp[i] = min(dp[i−1] + |h[i] − h[i−1]|, dp[i−2] + |h[i] − h[i−2]|).","Tham lam “nhảy tới hòn gần độ cao nhất” không đúng; thử với 30 10 60 10 60 50."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] h = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        long[] dp = new long[n];               // dp[i]: sức nhỏ nhất để tới hòn i (đánh số từ 0)\n        // xét cú nhảy cuối: từ i-1 hoặc từ i-2\n        Console.WriteLine(dp[n - 1]);\n    }\n}",hints:["dp[i]: sức nhỏ nhất để đứng ở hòn i. dp[0] = 0.","Cú nhảy cuối từ i − 1 hoặc i − 2: dp[i] = min(dp[i−1] + |h[i] − h[i−1]|, dp[i−2] + |h[i] − h[i−2]|).","Tham lam “nhảy tới hòn gần độ cao nhất” không đúng; thử với 30 10 60 10 60 50."]}},{t:"Chuỗi không có ba chữ liền giống nhau",d:"Đếm số chuỗi độ dài n gồm các chữ A, B, C mà không có ba chữ giống nhau đứng liền nhau (AAB được, AAA không). Đầu vào: n (1 ≤ n ≤ 10^6). Đầu ra: số chuỗi, lấy dư cho 10^9 + 7.",tests:[{in:"1",out:"3"},{in:"2",out:"9"},{in:"3",out:"24"},{in:"4",out:"66"},{in:"10",out:"27408"},{in:"1000",out:"411653997"},{in:"123456",out:"481656168"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    const long long MOD = 1000000007;\n    long long mot = 3, hai = 0;        // số chuỗi độ dài 1 kết thúc bằng một khối 1 chữ / 2 chữ giống nhau\n    // độ dài tăng từ 1 lên n: thêm chữ khác chữ cuối, hoặc thêm chữ giống (chỉ khi khối cuối dài 1)\n    cout << (mot + hai) % MOD << \"\\n\";\n    return 0;\n}",perf:{gen:n=>String(n),ns:[1000,2000,4000,8000],need:"n",limit:n=>40*n+300,why:"Liệt kê mọi chuỗi tốn 3^n."},py:{start:"n = int(input())\nMOD = 10**9 + 7\nmot, hai = 3, 0                # chuỗi độ dài 1 kết thúc bằng khối 1 chữ / 2 chữ giống nhau\n# độ dài tăng từ 1 lên n: thêm chữ khác chữ cuối, hoặc thêm chữ giống (chỉ khi khối cuối dài 1)\nprint((mot + hai) % MOD)",hints:["Chỉ biết số chuỗi độ dài i là không đủ: cần biết khối chữ giống nhau ở cuối dài 1 hay 2.","mot: chuỗi kết thúc bằng khối dài 1; hai: khối dài 2. Thêm chữ khác: (mot + hai) · 2 chuỗi vào mot. Thêm chữ giống: chỉ từ mot, vào hai.","Cơ sở n = 1: mot = 3, hai = 0. Gán đồng thời: mot, hai = (mot + hai) * 2 % MOD, mot."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        const long MOD = 1000000007;\n        long mot = 3, hai = 0;                 // chuỗi độ dài 1 kết thúc bằng khối 1 chữ / 2 chữ giống nhau\n        // độ dài tăng từ 1 lên n: thêm chữ khác chữ cuối, hoặc thêm chữ giống (chỉ khi khối cuối dài 1)\n        Console.WriteLine((mot + hai) % MOD);\n    }\n}",hints:["Chỉ biết số chuỗi độ dài i là không đủ: cần biết khối chữ giống nhau ở cuối dài 1 hay 2.","mot: chuỗi kết thúc bằng khối dài 1; hai: khối dài 2. Thêm chữ khác: (mot + hai) · 2 chuỗi vào mot. Thêm chữ giống: chỉ từ mot, vào hai.","Cơ sở n = 1: mot = 3, hai = 0. Chỉ cần giữ hai số của độ dài trước."]}}]);

